using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FloorWearVerify {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/FloorSurfaceWear/";static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};static bool Equal(JToken a,JToken b){if(a.Type!=b.Type&&!(a is JValue&&b is JValue))return false;if(a is JValue&&b is JValue){if(a.Type==JTokenType.Float||a.Type==JTokenType.Integer)return Math.Abs((double)a-(double)b)<.00002;return JToken.DeepEquals(a,b);}return a.Children().Count()==b.Children().Count()&&a.Children().Zip(b.Children(),Equal).All(q=>q);}
 static string Tri(Vector3 a,Vector3 b,Vector3 c)=>a.ToString("F6")+b.ToString("F6")+c.ToString("F6");
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string original=SceneManager.GetActiveScene().path;var log=new List<object>();var allowed=JArray.Parse(File.ReadAllText(R+"/SourceAssets/B4_DeskAndCollision/refined_colliders.json")).Select(q=>(string)q["id"]).ToHashSet();var lightFix=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B4_DeskAndCollision/collider_fix.json"));allowed.UnionWith(lightFix["changes"].Select(q=>(string)q["id"]));try{foreach(string f in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Circular.unity");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var state=JArray.FromObject(ts.Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,p=V(t.position),e=V(t.eulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf,colliders=t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,center=V(c.bounds.center),size=V(c.bounds.size),enabled=c.enabled,trigger=c.isTrigger,mesh=c is MeshCollider mc&&mc.sharedMesh?AssetDatabase.GetAssetPath(mc.sharedMesh):""}),lights=t.GetComponents<Light>().Select(l=>new{l.intensity,l.range,l.spotAngle,color=new[]{l.color.r,l.color.g,l.color.b},l.enabled})}));var old=JArray.Parse(File.ReadAllText(H+f+"_state_before.json"));var current=state.ToDictionary(j=>(string)j["id"]);var stateDiff=new List<object>();foreach(var j in old){string id=(string)j["id"];if(!current.TryGetValue(id,out var now)){stateDiff.Add(new{id,issue="missing"});continue;}foreach(string key in new[]{"name","p","e","scale","active","colliders","lights"}){if(key=="colliders"&&allowed.Contains(id))continue;if(!Equal(j[key],now[key]))stateDiff.Add(new{name=(string)j["name"],key,before=j[key],after=now[key]});}}
 var meshChecks=new List<object>();var renders=JArray.Parse(File.ReadAllText(H+f+"_renderers.json"));foreach(var j in renders){GlobalObjectId.TryParse((string)j["id"],out var gid);var rr=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as MeshRenderer;if(!rr)continue;var m=rr.GetComponent<MeshFilter>()?.sharedMesh;if(!m||!AssetDatabase.GetAssetPath(m).Contains("/FW_"))continue;var om=AssetDatabase.LoadAllAssetsAtPath((string)j["asset"]).OfType<Mesh>().Single(q=>q.name==(string)j["mesh"]);var ov=om.vertices;var oi=om.triangles;var nv=m.vertices;var ni=m.triangles;var triangles=new Dictionary<string,int>();for(int i=0;i<oi.Length;i+=3){string k=Tri(ov[oi[i]],ov[oi[i+1]],ov[oi[i+2]]);triangles.TryGetValue(k,out int n);triangles[k]=n+1;}int extra=0;for(int i=0;i<ni.Length;i+=3){string k=Tri(nv[ni[i]],nv[ni[i+1]],nv[ni[i+2]]);if(triangles.TryGetValue(k,out int n)&&n>0)triangles[k]=n-1;else extra++;}meshChecks.Add(new{name=rr.name,triangles=ni.Length/3,extra,missing=triangles.Values.Sum(),invalidUV=m.uv.Count(v=>float.IsNaN(v.x)||float.IsNaN(v.y)),missingMaterials=rr.sharedMaterials.Count(mat=>!mat)});}
 File.WriteAllText(H+f+"_state_after.json",state.ToString());log.Add(new{floor=f,transforms=ts.Length,oldTransforms=old.Count,stateDiff,lights=ts.Sum(t=>t.GetComponents<Light>().Length),meshChecks});}}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(R+"/Docs/Review/2026-11-09_FloorSurfaceWear/verification.json",JsonConvert.SerializeObject(log,Formatting.Indented));return log.Select(x=>new{floor=x.GetType().GetProperty("floor").GetValue(x),stateDiff=x.GetType().GetProperty("stateDiff").GetValue(x),meshCount=((System.Collections.ICollection)x.GetType().GetProperty("meshChecks").GetValue(x)).Count});}
}
